                    if route_load(rj) + dn > cap:
                        continue
                    for pos in range(len(rj) + 1):
                        gain = rem_delta - insertion_delta(rj, pos, node)
                        key = (i, j, p, pos, node)
                        if gain > best_gain + 1e-12 or (abs(gain - best_gain) <= 1e-12 and best_move is not None and key < best_move):
                            best_gain = gain
                            best_move = key
        if best_move is not None and best_gain > 1e-12:
            i, j, p, pos, node = best_move
            if i < j:
                routes[i].pop(p)
                routes[j].insert(pos, node)
            else:
                routes[j].insert(pos, node)
                routes[i].pop(p)
            routes = [r for r in routes if r]
            changed = True

    improved = True
    while improved:
        improved = False
        for idx in range(len(routes)):
            r = routes[idx]
            if len(r) < 4:
                continue
            best = r[:]
            best_cost = route_cost(r)
            n = len(r)
            for i in range(n - 1):
                for k in range(i + 2, n):
                    if i == 0 and k == n - 1:
                        continue
                    nr = r[:i + 1] + r[i + 1:k + 1][::-1] + r[k + 1:]
                    c = route_cost(nr)
                    if c + 1e-12 < best_cost or (abs(c - best_cost) <= 1e-12 and nr < best):
                        best = nr
                        best_cost = c
            if best != r:
                routes[idx] = best
                improved = True

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    extras = [c for c, v in seen.items() if v > 1]
    if missing or extras:
        flat = []
        for r in routes:
            flat.extend(r)
        uniq = []
        used = {}
        for c in flat:
            if c not in used:
                used[c] = 1
                uniq.append(c)
        for c in customers:
            if c not in used:
                uniq.append(c)
        routes = []
        current = []
        load = 0
        for c in uniq:
            d = demand_of(c)
            if load + d <= cap:
                current.append(c)
                load += d
            else:
                if current:
                    routes.append(current)
                current = [c]
                load = d
        if current:
            routes.append(current)

    return routes
